### 2. 核心算法：挥拍检测

```javascript
// common/swing-detector.js
class SwingDetector {
  constructor() {
    this.accelData = []
    this.isSwinging = false
    this.peakThreshold = 15 // m/s²，需根据实际调整
    this.minSwingDuration = 100 // ms
  }

  // 加速度数据回调
  onAccelerometerData(x, y, z) {
    const magnitude = Math.sqrt(x * x + y * y + z * z)
    const timestamp = Date.now()

    this.accelData.push({ magnitude, timestamp, x, y, z })

    // 保留最近 500ms 的数据
    const cutoff = timestamp - 500
    this.accelData = this.accelData.filter(d => d.timestamp > cutoff)

    // 检测挥拍峰值
    if (magnitude > this.peakThreshold && !this.isSwinging) {
      this.isSwinging = true
      this.onSwingDetected(this.analyzeSwing())
    }

    // 挥拍结束判定
    if (this.isSwinging && magnitude < 10) {
      this.isSwinging = false
    }
  }

  // 分析挥拍特征
  analyzeSwing() {
    const recentData = this.accelData.slice(-20) // 最近 20 个采样点

    // 计算特征
    const features = {
      peakAccel: Math.max(...recentData.map(d => d.magnitude)),
      avgAccel: recentData.reduce((s, d) => s + d.magnitude, 0) / recentData.length,
      duration: recentData[recentData.length - 1].timestamp - recentData[0].timestamp,
      direction: this.calculateDirection(recentData),
      timestamp: Date.now()
    }

    return features
  }

  // 计算挥拍方向
  calculateDirection(data) {
    const last = data[data.length - 1]
    const first = data[0]

    // 基于三轴变化判断方向
    if (Math.abs(last.y - first.y) > Math.abs(last.x - first.x)) {
      return last.y > first.y ? 'down' : 'up'
    } else {
      return last.x > first.x ? 'right' : 'left'
    }
  }
}

export default new SwingDetector()
```

### 3. 核心算法：击球分类（规则引擎）

```javascript
// common/shot-classifier.js
class ShotClassifier {
  constructor() {
    // 基于加速度特征的分类规则
    // 由于没有陀螺仪，分类精度会受限
    this.rules = {
      // 高远球：高加速度，持续时间长，向上方向
      highClear: {
        minPeakAccel: 18,
        minDuration: 150,
        direction: 'up',
        confidence: 0.6
      },
      // 杀球：极高加速度，短促，向下方向
      smash: {
        minPeakAccel: 25,
        maxDuration: 120,
        direction: 'down',
        confidence: 0.7
      },
      // 平抽：中等加速度，水平方向
      drive: {
        minPeakAccel: 15,
        maxPeakAccel: 22,
        direction: 'horizontal',
        confidence: 0.5
      },
      // 挑球：低加速度，向上
      lift: {
        maxPeakAccel: 15,
        direction: 'up',
        confidence: 0.5
      }
    }
  }

  classify(swingFeatures) {
    const results = []

    for (const [type, rule] of Object.entries(this.rules)) {
      let match = true
      let score = 0

      // 检查峰值加速度
      if (rule.minPeakAccel && swingFeatures.peakAccel < rule.minPeakAccel) match = false
      if (rule.maxPeakAccel && swingFeatures.peakAccel > rule.maxPeakAccel) match = false

      // 检查持续时间
      if (rule.minDuration && swingFeatures.duration < rule.minDuration) match = false
      if (rule.maxDuration && swingFeatures.duration > rule.maxDuration) match = false

      // 检查方向
      if (rule.direction !== 'horizontal') {
        if (swingFeatures.direction !== rule.direction) match = false
      }

      if (match) {
        results.push({
          type,
          confidence: rule.confidence,
          features: swingFeatures
        })
      }
    }

    // 按置信度排序
    results.sort((a, b) => b.confidence - a.confidence)

    return results.length > 0 ? results[0] : { type: 'unknown', confidence: 0 }
  }
}

export default new ShotClassifier()
```

### 4. 健康数据监控

```javascript
// common/health-monitor.js
import health from '@system.health'

class HealthMonitor {
  constructor() {
    this.isMonitoring = false
    this.currentHeartRate = 0
    this.totalCalories = 0
    this.startTime = null
  }

  start() {
    this.isMonitoring = true
    this.startTime = Date.now()

    // 订阅心率数据
    health.subscribeSample({
      dataType: 0, // HEART_RATE
      callback: (data) => {
        this.currentHeartRate = data.value
        this.updateCalories()
      },
      fail: (data) => {
        console.error('心率订阅失败:', data.code)
      }
    })
  }

  stop() {
    this.isMonitoring = false
    health.unsubscribeSample({
      dataType: 0
    })
  }

  updateCalories() {
    // 基于心率估算卡路里消耗
    // 简化公式： calories = duration(min) * MET * weight(kg) / 60
    // MET ≈ 心率 / 100 (简化估算)
    if (this.startTime && this.currentHeartRate > 0) {
      const durationMin = (Date.now() - this.startTime) / 60000
      const met = this.currentHeartRate / 100
      this.totalCalories = durationMin * met * 70 / 60 // 假设体重 70kg
    }
  }

  getData() {
    return {
      heartRate: this.currentHeartRate,
      calories: Math.round(this.totalCalories),
      duration: this.startTime ? Math.round((Date.now() - this.startTime) / 1000) : 0
    }
  }
}

export default new HealthMonitor()
```

