  import sensor from '@system.sensor'
  import swingDetector from '../../common/swing-detector'
  import shotClassifier from '../../common/shot-classifier'
  import healthMonitor from '../../common/health-monitor'
  import dataStore from '../../common/data-store'

  export default {
    data: {
      isMonitoring: false,
      swingCount: 0,
      lastShotType: '--',
      heartRate: '--',
      calories: 0,
      duration: 0,
      swingScale: 1,
      statusText: '就绪'
