      swingDetector.onSwingDetected = (features) => {
        this.swingCount++
        this.animateSwing()

        // 分类击球类型
        const result = shotClassifier.classify(features)
        this.lastShotType = this.getShotName(result.type)

        // 保存数据
        this.saveData()
      }

      // 启动健康监测
      healthMonitor.start()

      // 定时更新健康数据
      this.healthTimer = setInterval(() => {
        const healthData = healthMonitor.getData()
        this.heartRate = healthData.heartRate || '--'
        this.calories = healthData.calories
        this.duration = healthData.duration
      }, 1000)
    },

    stopMonitoring() {
      this.isMonitoring = false
      this.statusText = '已停止'

      // 停止加速度计
      sensor.unsubscribeAccelerometer()

      // 停止健康监测
      healthMonitor.stop()

      // 清除定时器
      if (this.healthTimer) {
        clearInterval(this.healthTimer)
      }

      // 保存数据
      this.saveData()
    },

    resetData() {
      this.swingCount = 0
      this.lastShotType = '--'
      this.heartRate = '--'
      this.calories = 0
      this.duration = 0
      healthMonitor.startTime = null
      healthMonitor.totalCalories = 0
    },

    animateSwing() {
      this.swingScale = 1.2
      setTimeout(() => {
        this.swingScale = 1
      }, 200)
    },

    getShotName(type) {
      const names = {
        highClear: '高远球',
        smash: '杀球',
        drive: '平抽',
        lift: '挑球',
        unknown: '未知'
      }
      return names[type] || type
    },

    loadData() {
      const data = dataStore.get('sessionData')
      if (data) {
        this.swingCount = data.swingCount || 0
      }
    },

    saveData() {
      dataStore.set('sessionData', {
        swingCount: this.swingCount,
        lastShotType: this.lastShotType,
        timestamp: Date.now()
      })
    }
  }
