```javascript
// common/imu-manager.js
import sensor from '@system.sensor'

class IMUManager {
  constructor() {
    this.accelData = { x: 0, y: 0, z: 0 }
    this.gyroData = { x: 0, y: 0, z: 0 }
    this.listeners = []
    this.isRunning = false
  }

  start(callback) {
    if (this.isRunning) return
    this.isRunning = true

    // 订阅加速度计 (最高频率 game 模式 ~50Hz)
    sensor.subscribeAccelerometer({
      interval: 'game',
      callback: (data) => {
        this.accelData = { x: data.x, y: data.y, z: data.z }
        this.notifyListeners()
      }
    })

    // 订阅陀螺仪 (最高频率 game 模式 ~50Hz)
    sensor.subscribeGyroscope({
      interval: 'game',
      callback: (data) => {
        this.gyroData = { x: data.x, y: data.y, z: data.z }
      }
    })
  }

  stop() {
    sensor.unsubscribeAccelerometer()
    sensor.unsubscribeGyroscope()
    this.isRunning = false
  }

  ondata(callback) {
    this.listeners.push(callback)
  }

  notifyListeners() {
    const data = {
      accel: { ...this.accelData },
      gyro: { ...this.gyroData },
      timestamp: Date.now()
    }
    this.listeners.forEach(cb => cb(data))
  }

  // 计算合加速度
  getAccelMagnitude() {
    const { x, y, z } = this.accelData
    return Math.sqrt(x * x + y * y + z * z)
  }

  // 计算合角速度
  getGyroMagnitude() {
    const { x, y, z } = this.gyroData
    return Math.sqrt(x * x + y * y + z * z)
  }
}

export default new IMUManager()
