## 三、击球检测与分类算法

```javascript
// common/swing-classifier.js
class SwingClassifier {
  constructor() {
    this.dataBuffer = []
    this.bufferSize = 50 // 50 个采样点 = 1 秒 (50Hz)
    this.isSwinging = false
    this.swingStart = 0
    this.swingData = []

    // 挥拍检测阈值
    this.thresholds = {
      accelPeak: 18,      // 加速度峰值阈值 (m/s²)
      gyroPeak: 3,        // 角速度峰值阈值 (rad/s)
      minDuration: 80,    // 最小挥拍时长 (ms)
      maxDuration: 400    // 最大挥拍时长 (ms)
    }

    // 击球类型特征 (基于六轴数据)
    this.shotProfiles = {
      // 高远球: 高加速度 + 中等角速度 + 向上挥拍
      highClear: {
        accelMin: 18, accelMax: 28,
        gyroMin: 2, gyroMax: 5,
        direction: 'up',
        swingAngle: 'high',
        confidence: 0.75
      },
      // 杀球: 极高加速度 + 高角速度 + 向下挥拍
      smash: {
        accelMin: 28, accelMax: 40,
        gyroMin: 5, gyroMax: 8,
        direction: 'down',
        swingAngle: 'steep',
        confidence: 0.85
      },
      // 平抽: 中等加速度 + 低角速度 + 水平挥拍
      drive: {
        accelMin: 15, accelMax: 25,
        gyroMin: 1, gyroMax: 3,
        direction: 'horizontal',
        swingAngle: 'flat',
        confidence: 0.7
      },
      // 挑球: 低加速度 + 中等角速度 + 向上挥拍
      lift: {
        accelMin: 12, accelMax: 18,
        gyroMin: 2, gyroMax: 4,
        direction: 'up',
        swingAngle: 'low',
        confidence: 0.65
      },
      // 吊球: 中等加速度 + 高角速度 + 轻柔挥拍
      drop: {
        accelMin: 14, accelMax: 20,
        gyroMin: 4, gyroMax: 6,
        direction: 'down',
        swingAngle: 'gentle',
        confidence: 0.6
      }
    }
  }

  // 处理 IMU 数据
  onIMUData(data) {
    // 添加到缓冲区
    this.dataBuffer.push(data)
    if (this.dataBuffer.length > this.bufferSize) {
      this.dataBuffer.shift()
    }

    // 检测挥拍
    const accelMag = this.calcMagnitude(data.accel)
    const gyroMag = this.calcMagnitude(data.gyro)

    // 挥拍开始检测
    if (!this.isSwinging && 
        (accelMag > this.thresholds.accelPeak || 
         gyroMag > this.thresholds.gyroPeak)) {
      this.isSwinging = true
      this.swingStart = data.timestamp
      this.swingData = [data]
    }

    // 挥拍进行中
    if (this.isSwinging) {
      this.swingData.push(data)
    }

    // 挥拍结束检测
    if (this.isSwinging && 
        accelMag < 10 && 
        gyroMag < 1.5 &&
        (data.timestamp - this.swingStart) > this.thresholds.minDuration) {

      this.isSwinging = false
      const duration = data.timestamp - this.swingStart

      if (duration <= this.thresholds.maxDuration) {
        // 分析挥拍
        const analysis = this.analyzeSwing(this.swingData)
        return analysis
      }
    }

    return null
  }

  // 分析挥拍特征
  analyzeSwing(swingData) {
    if (swingData.length < 5) return null

    // 提取特征
    const features = this.extractFeatures(swingData)

    // 分类击球类型
    const classification = this.classify(features)

    return {
      type: classification.type,
      confidence: classification.confidence,
      features: features,
      timestamp: swingData[swingData.length - 1].timestamp
    }
  }

  // 提取挥拍特征
  extractFeatures(data) {
    const accelValues = data.map(d => this.calcMagnitude(d.accel))
    const gyroValues = data.map(d => this.calcMagnitude(d.gyro))

    // 计算统计特征
    const features = {
      // 加速度特征
      accelPeak: Math.max(...accelValues),
      accelMean: this.mean(accelValues),
      accelStd: this.std(accelValues),
      accelSlope: this.calcSlope(accelValues),

      // 角速度特征
      gyroPeak: Math.max(...gyroValues),
      gyroMean: this.mean(gyroValues),
      gyroStd: this.std(gyroValues),
      gyroSlope: this.calcSlope(gyroValues),

      // 时域特征
      duration: data[data.length - 1].timestamp - data[0].timestamp,
      sampleCount: data.length,

      // 方向特征
      direction: this.calcDirection(data),
      swingAngle: this.calcSwingAngle(data),

      // 能量特征
      energy: this.calcEnergy(accelValues, gyroValues)
    }

    return features
  }

  // 计算方向 (基于加速度变化)
  calcDirection(data) {
    const start = data.slice(0, 5)
    const end = data.slice(-5)

    const startAvgY = this.mean(start.map(d => d.accel.y))
    const endAvgY = this.mean(end.map(d => d.accel.y))

    // 重力加速度约 9.8，判断挥拍方向
    if (endAvgY > startAvgY + 2) return 'down'
    if (endAvgY < startAvgY - 2) return 'up'
    return 'horizontal'
  }

  // 计算挥拍角度
  calcSwingAngle(data) {
    const accelY = data.map(d => d.accel.y)
    const maxAccel = Math.max(...accelY)
    const minAccel = Math.min(...accelY)
    const range = maxAccel - minAccel

    if (range > 15) return 'steep'   // 大幅度挥拍
    if (range > 8) return 'high'     // 中等幅度
    if (range > 4) return 'flat'     // 小幅度
    return 'gentle'                   // 轻柔挥拍
  }

  // 计算能量
  calcEnergy(accelValues, gyroValues) {
    const accelEnergy = accelValues.reduce((sum, v) => sum + v * v, 0)
    const gyroEnergy = gyroValues.reduce((sum, v) => sum + v * v, 0)
    return accelEnergy + gyroEnergy * 10 // 角速度权重
  }

  // 分类击球类型
  classify(features) {
    let bestMatch = { type: 'unknown', confidence: 0 }

    for (const [type, profile] of Object.entries(this.shotProfiles)) {
      let score = 0
      let matchCount = 0
      let totalChecks = 0

      // 检查加速度
      if (features.accelPeak >= profile.accelMin && 
          features.accelPeak <= profile.accelMax) {
        score += 0.3
        matchCount++
      }
      totalChecks++

      // 检查角速度
      if (features.gyroPeak >= profile.gyroMin && 
          features.gyroPeak <= profile.gyroMax) {
        score += 0.3
        matchCount++
      }
      totalChecks++

      // 检查方向
      if (features.direction === profile.direction) {
        score += 0.2
        matchCount++
      }
      totalChecks++

      // 检查挥拍角度
      if (features.swingAngle === profile.swingAngle) {
        score += 0.2
        matchCount++
      }
      totalChecks++

      // 综合置信度
      const confidence = (score * profile.confidence) * (matchCount / totalChecks)

      if (confidence > bestMatch.confidence) {
        bestMatch = { type, confidence }
      }
    }

    return bestMatch
  }

  // 辅助函数
  calcMagnitude(vec) {
    return Math.sqrt(vec.x * vec.x + vec.y * vec.y + vec.z * vec.z)
  }

  mean(arr) {
    return arr.reduce((a, b) => a + b, 0) / arr.length
  }

  std(arr) {
    const m = this.mean(arr)
    return Math.sqrt(arr.reduce((sum, v) => sum + (v - m) ** 2, 0) / arr.length)
  }

  calcSlope(arr) {
    const n = arr.length
    const sumX = arr.reduce((s, _, i) => s + i, 0)
    const sumY = arr.reduce((s, v) => s + v, 0)
    const sumXY = arr.reduce((s, v, i) => s + i * v, 0)
    const sumX2 = arr.reduce((s, _, i) => s + i * i, 0)
    return (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX)
  }
}

export default new SwingClassifier()
